/// Find the tspec for a crate - either explicit path/name or default tspec.toml
pub fn find_tspec(workspace: &Path, crate_dir: &Path, explicit: Option<&str>) -> Result<PathBuf> {
    match explicit {
        Some(name_or_path) => {
            // First try as a direct path
            let p = PathBuf::from(name_or_path);
            if p.exists() {
                return Ok(p);
            }
            // Then try as a library name: libs/<name>/tspec.toml
            let lib_spec = workspace.join("libs").join(name_or_path).join("tspec.toml");
            if lib_spec.exists() {
                return Ok(lib_spec);
            }
            bail!(
                "tspec not found: {} (tried as path and libs/{}/tspec.toml)",
                name_or_path,
                name_or_path
            );
        }
        None => {
            let default = crate_dir.join("tspec.toml");
            if default.exists() {
                Ok(default)
            } else {
                bail!(
                    "no tspec.toml found in {} (use -t to specify)",
                    crate_dir.display()
                );
            }
        }
    }
}

